import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useIntl } from 'react-intl';

import { SegmentedControl } from '@hexa-ui/components';
import { Alert, Cover, StickyScrollWithFilters } from 'components';
import { TableOfContents } from 'components/TableOfContents';
import { useGlobalDataAvailability } from 'contexts';
import { useDataRefreshForTab } from 'contexts/DataRefreshModal/useDataRefreshForTab';
import { FilterDataAccessor } from 'domain/Filter';
import {
  useExportPdf,
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterStatus,
} from 'hooks';
import {
  StyledGlobalDataBanner,
  StyledGridContainer,
  StyledGridItem,
} from 'shared/Styles';
import {
  StyledExportButton,
  StyledExportIcon,
  StyledExportPageContent,
  StyledExportPageHeader,
  StyledExportPageSection,
} from 'shared/Styles/exportPages.styles';

import { CountryInlineView, CountryView, GlobalView } from './components';
import type { LazyMountHandle } from './components/LazySlide';
import { LazyMountProvider } from './components/LazySlide';
import { pageSections } from './constants';
import { buildCoverPeriod } from './helpers';
import { useAllCountriesData } from './hooks/useAllCountriesData';
import { usePowerBookGlobalData } from './hooks/usePowerBookGlobalData/usePowerBookGlobalData';
import { usePowerBookPeriods } from './hooks/usePowerBookPeriods/usePowerBookPeriods';
import { useTocGroups } from './hooks/useTocGroups/useTocGroups';

export const BRAND_POWER_BOOK_EXPORT_PAGE_NAME =
  'portfolio-brand_brand-power-results-export';
const ExportIcon = () => <StyledExportIcon />;

type BookMode = 'executive' | 'complete';

const BOOK_MODE_OPTIONS = [
  { value: 'executive' as const, label: 'Executive' },
  { value: 'complete' as const, label: 'Complete Book' },
];

export const BrandPowerBookExport: React.FC = () => {
  useDataRefreshForTab('Brand Power Book - Power Book');
  const { formatMessage } = useIntl();
  const { shouldShowGlobalBanner } = useGlobalDataAvailability();
  const { applied } = usePageFilterApplied(BRAND_POWER_BOOK_EXPORT_PAGE_NAME);
  const { dataFilters } = usePageFilterData(BRAND_POWER_BOOK_EXPORT_PAGE_NAME);
  const { isLoading: filtersLoading } = usePageFilterStatus(
    BRAND_POWER_BOOK_EXPORT_PAGE_NAME,
  );
  const country = useMemo(() => {
    return FilterDataAccessor.getInstance().getCountry(dataFilters, applied);
  }, [dataFilters, applied]);

  useEffect(() => {
    window.scrollTo({ top: 0 });
  }, [country?.value]);

  const containerRef = useRef<HTMLDivElement>(null);
  const lazyMountRef = useRef<LazyMountHandle>(null);
  const [bookMode, setBookMode] = useState<BookMode>('executive');
  const [isLoadingCountry, setIsLoadingCountry] = useState(true);
  const [isPreparing, setIsPreparing] = useState(false);

  const {
    qtdPeriod,
    ytdPeriod,
    ytdSubCoverLabel,
    qtdCoverPrefix,
    qtdCoverYear,
    fiscalYear,
    quarterYearFull,
  } = usePowerBookPeriods();

  const period = useMemo(
    () => buildCoverPeriod(qtdCoverPrefix, qtdCoverYear),
    [qtdCoverPrefix, qtdCoverYear],
  );

  const { onExport, isExporting } = useExportPdf(
    useMemo(
      () => ({
        scale: 1.5,
        format: 'a4' as const,
        orientation: 'landscape' as const,
        margin: 0,
        preserveLinks: true,
        quality: 1,
        imageFormat: 'JPEG' as const,
        compression: true,
        improveCanvasQuality: true,
      }),
      [],
    ),
  );

  const handlePDFExport = useCallback(async () => {
    setIsPreparing(true);
    await lazyMountRef.current?.mountAll();
    const pages = containerRef.current?.querySelectorAll('[data-page-name]');
    onExport(Array.from(pages ?? []) as HTMLElement[]);
    setIsPreparing(false);
  }, [onExport]);

  const countries = useMemo(
    () => [
      {
        code: String(country?.value) || '',
        name: String(country?.label) || '',
      },
    ],
    [country?.value, country?.label],
  );

  const isGlobalView = countries[0].code === 'ABI';
  const isCompleteBook = isGlobalView && bookMode === 'complete';

  const {
    qtdData,
    ytdData,
    qtdDone,
    loading: globalLoading,
  } = usePowerBookGlobalData(false, !filtersLoading && isGlobalView);

  const skipCountries = !isCompleteBook || !qtdDone;

  const { countries: allCountriesData, loading: countriesLoading } =
    useAllCountriesData(skipCountries);

  const handleTocItemClick = useCallback((slideId: string) => {
    lazyMountRef.current?.scrollToSlide(slideId);
  }, []);

  const tocGroups = useTocGroups(quarterYearFull, fiscalYear);

  const renderView = useCallback((): JSX.Element | null => {
    if (!countries[0].code) return null;

    if (isGlobalView) {
      return (
        <>
          <GlobalView
            containerRef={containerRef}
            qtdData={qtdData}
            ytdData={ytdData}
            isCompleteBook={isCompleteBook}
          />
          {isCompleteBook && (
            <>
              <StyledExportPageSection
                data-page-name={pageSections.coverMarketsDeepDive}
              >
                <Cover
                  category="One Way Reports"
                  name="Markets Deep Dive"
                  loading={false}
                  period={period}
                  showLogo
                />
              </StyledExportPageSection>
              <CountryInlineView
                containerRef={containerRef}
                countriesData={allCountriesData}
                loading={countriesLoading}
                qtdPeriod={qtdPeriod}
                ytdPeriod={ytdPeriod}
                ytdSubCoverLabel={ytdSubCoverLabel}
                qtdCoverPrefix={qtdCoverPrefix}
                coverPeriod={period}
              />
            </>
          )}
        </>
      );
    }

    return (
      <CountryView
        containerRef={containerRef}
        loadingCallback={setIsLoadingCountry}
      />
    );
  }, [
    countries,
    containerRef,
    isGlobalView,
    isCompleteBook,
    allCountriesData,
    countriesLoading,
    qtdData,
    ytdData,
    qtdPeriod,
    ytdPeriod,
    ytdSubCoverLabel,
    qtdCoverPrefix,
    period,
  ]);

  const isLoading = useMemo(() => {
    if (isGlobalView) {
      return isCompleteBook ? globalLoading || countriesLoading : globalLoading;
    }
    return isLoadingCountry;
  }, [
    globalLoading,
    isGlobalView,
    isCompleteBook,
    countriesLoading,
    isLoadingCountry,
  ]);

  return (
    <>
      <StickyScrollWithFilters
        filter={{
          pageName: BRAND_POWER_BOOK_EXPORT_PAGE_NAME,
          visibleFields: ['zone', 'country', 'time_frame'],
          dataTestId: 'brand-power-book-export-filter',
        }}
        breadcrumbs={{
          pageList: [
            {
              href: '/portfolio-brand',
              pageName: formatMessage({
                id: 'Pillars.pageName.portfolioBrand',
              }),
            },
            {
              href: '/portfolio-brand/brand-power-book-export',
              pageName: formatMessage({
                id: 'Sidebar.brandPowerBookExport',
              }),
            },
          ],
          showIcon: true,
        }}
        isExportPage
      />

      <StyledGridContainer isExportPage>
        {shouldShowGlobalBanner('power') && (
          <StyledGlobalDataBanner>
            <Alert
              type="warning"
              position="inline"
              title={formatMessage({ id: 'GlobalData.bannerTitle' })}
              message={formatMessage({ id: 'GlobalData.bannerMessage' })}
              dataTestId="global-data-banner-power"
            />
          </StyledGlobalDataBanner>
        )}
        <StyledGridItem xs={12} sm={12} md={12} lg={12} xl={12}>
          <LazyMountProvider ref={lazyMountRef}>
            <StyledExportPageContent ref={containerRef} noMargin>
              <StyledExportPageHeader>
                {isGlobalView && (
                  <SegmentedControl
                    value={bookMode}
                    onValueChange={(v) => setBookMode(v as BookMode)}
                    options={BOOK_MODE_OPTIONS}
                    css={{ alignSelf: 'flex-end' }}
                    data-testid="book-mode-toggle"
                  />
                )}
                {!isCompleteBook && (
                  <StyledExportButton
                    variant="primary"
                    size="medium"
                    onClick={handlePDFExport}
                    data-testid="refresh-button"
                    isLoading={isExporting || isLoading || isPreparing}
                    icon={ExportIcon}
                    trailing
                  >
                    Export File
                  </StyledExportButton>
                )}
              </StyledExportPageHeader>

              <StyledExportPageSection data-page-name={pageSections.cover}>
                <Cover
                  category="One Way Reports"
                  name="Brand Power Book"
                  countries={countries}
                  loading={filtersLoading}
                  period={period}
                  showLogo
                />
              </StyledExportPageSection>

              {isCompleteBook && (
                <StyledExportPageSection
                  data-page-name={pageSections.tableOfContents}
                >
                  <TableOfContents
                    title="Table of Contents"
                    groups={tocGroups}
                    onItemClick={handleTocItemClick}
                    dataTestId="complete-book-toc"
                  />
                </StyledExportPageSection>
              )}

              {renderView()}

              <StyledExportPageSection data-page-name={pageSections.backCover}>
                <Cover
                  name="Thank You"
                  centerLogo
                  showLogo
                  dataTestId={`${BRAND_POWER_BOOK_EXPORT_PAGE_NAME}-thank-you`}
                />
              </StyledExportPageSection>
            </StyledExportPageContent>
          </LazyMountProvider>
        </StyledGridItem>
      </StyledGridContainer>
    </>
  );
};
